starter.css:
.speaker { width: 160px; }
.photo {
  width: 100%;
  background: #ede9fe;
  border-radius: 12px;
}
.toast {
  position: fixed;
  left: 16px;
  bottom: 16px;
  padding: 8px 14px;
  border-radius: 8px;
  background: #1f2937;
  color: white;
  animation: toast-in 250ms ease-out;
}

@keyframes toast-in {
  from { left: -320px; }
  to { left: 16px; }
}

solution.css:
.speaker { width: 160px; }
.photo {
  width: 100%;
  background: #ede9fe;
  border-radius: 12px;
}
.toast {
  position: fixed;
  left: 16px;
  bottom: 16px;
  padding: 8px 14px;
  border-radius: 8px;
  background: #1f2937;
  color: white;
  animation: toast-in 250ms ease-out;
}
.photo { aspect-ratio: 1; }

.day {
  content-visibility: auto;
  contain-intrinsic-size: auto 1200px;
}

@keyframes toast-in {
  from { translate: -336px 0; opacity: 0; }
  to { translate: 0 0; opacity: 1; }
}
